root_hex = "c6594e6e352360bc2b09e7dd36ab2e148e0b31182dcc64d032f05630cbccc242"

n = 247+1

list_key256first = []

def dsha256(b: bytes) -> bytes:
    return hashlib.sha256(hashlib.sha256(b).digest()).digest()


def leaf_hash(item: bytes) -> bytes:
    return dsha256(item)


def node_hash(left: bytes, right: bytes) -> bytes:
    return dsha256(left + right)


def merkle_computation(leaves: list[bytes]) -> bytes:
    if len(leaves) == 0:
        return b"\x00" * 32
    count = 0
    inner = [None] * 32
    while count < len(leaves):
        h = leaves[count]
        count += 1
        level = 0
        while not (count & (1 << level)):
            h = dsha256(inner[level] + h)
            if (count == n):
                list_key256first.append((inner[level].hex()+":L"))
            level += 1
        inner[level] = h
    Proof1 = list_key256first.copy()
    Proof2 = list_key256first.copy()
    while h != bytes.fromhex(root_hex):
        Proof1.append(h.hex()+":L")
        Proof2.append(h.hex()+":R")
        h = dsha256(h + h)
        count += 1 << level
        level += 1
        while not (count & (1 << level)):
            h = dsha256(inner[level] + h)
            Proof1.append(inner[level].hex()+":L")
            Proof2.append(inner[level].hex()+":L")
            level += 1
    return Proof1,Proof2

